import ctypes
import threading
import uuid
from collections import defaultdict
from contextlib import contextmanager

# Native buffer pool for high-performance tenant data processing
class NativeBuffer:
    """Wraps a malloc'd buffer for zero-copy tenant data operations."""

    _libc = ctypes.CDLL("libc.so.6")
    _libc.malloc.restype = ctypes.c_void_p
    _libc.malloc.argtypes = [ctypes.c_size_t]
    _libc.free.argtypes = [ctypes.c_void_p]
    _libc.free.restype = None
    _libc.memcpy.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t]
    _libc.memcpy.restype = ctypes.c_void_p

    def __init__(self, size: int):
        if not isinstance(size, int) or isinstance(size, bool):
            raise TypeError("size must be an integer")
        if size <= 0:
            raise ValueError("size must be a positive integer")
        self.size = size
        self._ptr = self._libc.malloc(size)
        if not self._ptr:
            raise MemoryError(f"Failed to allocate {size} bytes")
        self._freed = False
        self._ref_count = 1
        self._lock = threading.Lock()

    def acquire(self):
        with self._lock:
            if self._freed:
                raise ValueError("Buffer already freed")
            self._ref_count += 1
            return self

    def release(self):
        should_free = False
        with self._lock:
            self._ref_count -= 1
            if self._ref_count <= 0:
                should_free = True
                self._freed = True
        if should_free:
            self._do_free()

    def _do_free(self):
        if self._ptr:
            self._libc.free(self._ptr)
            self._ptr = None

    def write(self, data: bytes, offset: int = 0):
        if self._freed:
            raise ValueError("Buffer already freed")
        if offset < 0:
            raise ValueError("offset must be non-negative")
        if offset + len(data) > self.size:
            raise ValueError("Write exceeds buffer size")
        src = ctypes.create_string_buffer(data)
        self._libc.memcpy(self._ptr + offset, ctypes.addressof(src), len(data))

    @property
    def ptr(self):
        return self._ptr


class TenantBufferPool:
    """Per-tenant buffer pool with isolation guarantees."""

    def __init__(self, max_buffers_per_tenant: int = 64):
        self._pools = defaultdict(list)  # tenant_id -> [NativeBuffer]
        self._active = defaultdict(dict)  # tenant_id -> {buf_id: NativeBuffer}
        self._max = max_buffers_per_tenant
        self._global_lock = threading.RLock()

    def allocate(self, tenant_id: str, size: int) -> str:
        """Allocate a buffer for a tenant, returns buffer_id."""
        with self._global_lock:
            if len(self._active[tenant_id]) >= self._max:
                raise ResourceWarning(f"Tenant {tenant_id} exceeded buffer limit")

            # Always allocate fresh - no reuse of freed buffers
            buf = NativeBuffer(size)

            buf_id = str(uuid.uuid4())
            self._active[tenant_id][buf_id] = buf
            return buf_id

    def get_buffer(self, tenant_id: str, buf_id: str) -> NativeBuffer:
        """Get a buffer reference for a tenant."""
        with self._global_lock:
            tenant_bufs = self._active.get(tenant_id, {})
            if buf_id not in tenant_bufs:
                raise PermissionError(f"Buffer {buf_id} not owned by tenant {tenant_id}")
            return tenant_bufs[buf_id].acquire()

    def deallocate(self, tenant_id: str, buf_id: str):
        """Free buffer completely."""
        with self._global_lock:
            tenant_bufs = self._active.get(tenant_id, {})
            if buf_id not in tenant_bufs:
                raise PermissionError(f"Buffer {buf_id} not owned by tenant {tenant_id}")

            buf = tenant_bufs.pop(buf_id)
            buf.release()

    def evict_tenant(self, tenant_id: str):
        """Evict all resources for a tenant."""
        with self._global_lock:
            # Free active buffers
            for buf_id, buf in list(self._active[tenant_id].items()):
                buf.release()
            del self._active[tenant_id]

            # No pool to clean - we don't cache freed buffers
            if tenant_id in self._pools:
                del self._pools[tenant_id]


class DataProcessor:
    """Multi-tenant data processing service."""

    def __init__(self):
        self._pool = TenantBufferPool()
        self._processing_lock = threading.Lock()

    def process_batch(self, tenant_id: str, data_chunks: list):
        """Process a batch of data for a tenant."""
        buf_ids = []
        try:
            for chunk in data_chunks:
                if len(chunk) == 0:
                    continue
                buf_id = self._pool.allocate(tenant_id, len(chunk))
                buf_ids.append(buf_id)
                buf = self._pool.get_buffer(tenant_id, buf_id)
                try:
                    buf.write(chunk)
                finally:
                    buf.release()

            # Simulate processing
            self._do_processing(tenant_id, buf_ids)
        finally:
            for buf_id in buf_ids:
                try:
                    self._pool.deallocate(tenant_id, buf_id)
                except (PermissionError, ValueError):
                    pass

    def _do_processing(self, tenant_id: str, buf_ids: list):
        """Internal processing step."""
        pass

    def cleanup_tenant(self, tenant_id: str):
        """Called when tenant session ends."""
        self._pool.evict_tenant(tenant_id)


# Service endpoint simulation
def handle_request(processor: DataProcessor, tenant_id: str, action: str, payload: dict):
    """Handle incoming tenant request."""
    if action == "process":
        data = [chunk.encode() for chunk in payload.get("chunks", [])]
        processor.process_batch(tenant_id, data)
        return {"status": "ok"}
    elif action == "cleanup":
        processor.cleanup_tenant(tenant_id)
        return {"status": "cleaned"}
    else:
        return {"status": "error", "msg": "unknown action"}
